# Let's try a simple backtracking approach with heuristics
import sys
sys.setrecursionlimit(10000)

n = 32
edges = [
(0,5), (0,10), (0,24), (0,28), (1,5), (1,15), (1,16), (1,18), (1,19), (1,20), (1,25), (2,13), (2,15), (2,20), (2,22), (3,23), (3,30), (3,31), (4,12), (4,23), (4,29), (5,8), (5,12), (5,17), (5,19), (5,23), (5,30), (6,8), (6,13), (6,28), (6,29), (6,30), (6,31), (7,18), (7,23), (7,28), (7,31), (8,10), (8,31), (9,11), (9,12), (9,18), (9,22), (9,25), (10,12), (10,16), (10,26), (10,29), (11,14), (11,16), (11,17), (11,26), (12,13), (12,14), (12,17), (12,30), (14,17), (14,21), (14,25), (14,27), (15,24), (15,26), (15,28), (16,18), (16,20), (16,30), (17,23), (17,28), (17,29), (18,27), (18,29), (19,20), (21,23), (21,31), (22,28), (23,25), (23,30), (23,31), (24,25), (24,30), (24,31), (25,26), (27,28), (28,30), (30,31)
]

adj = [[] for _ in range(n)]
for u,v in edges:
    adj[u].append(v)
    adj[v].append(u)

# DSATUR algorithm
colors = [-1] * n

def get_saturation(v, colors):
    used = set()
    for nb in adj[v]:
        if colors[nb] != -1:
            used.add(colors[nb])
    return len(used)

def get_available_colors(v, colors):
    used = set()
    for nb in adj[v]:
        if colors[nb] != -1:
            used.add(colors[nb])
    return [c for c in range(4) if c not in used]

def select_vertex(colors):
    best_v = -1
    best_sat = -1
    best_deg = -1
    for v in range(n):
        if colors[v] == -1:
            sat = get_saturation(v, colors)
            deg = len(adj[v])
            if sat > best_sat or (sat == best_sat and deg > best_deg):
                best_sat = sat
                best_deg = deg
                best_v = v
    return best_v

def backtrack(colors):
    v = select_vertex(colors)
    if v == -1:
        return True  # all colored

    avail = get_available_colors(v, colors)
    # Try colors in some order - maybe least constraining first
    # For simplicity, try 0,1,2,3
    for c in avail:
        colors[v] = c
        if backtrack(colors):
            return True
        colors[v] = -1
    return False

if backtrack(colors):
    print("SAT")
    print(colors)
else:
    print("UNSAT")
